 "content": "def transform(grid):
    g = [row[:] for row in grid]
    n, m = len(g), len(g[0])
    # The pattern consists of two 2x2 squares. The four colored corner-pairs
    # around them are reflected across the line joining the squares: each corner
    # marker emits a diagonal ray outward along the square's corner orientation.
    # For each colored marker, extend its diagonal away from the closest 2x2 block.
    blocks = []
    for r in range(n-1):
        for c in range(m-1):
            if all(grid[rr][cc] == 2 for rr in (r,r+1) for cc in (c,c+1)):
                blocks.append((r,c))
    for r in range(n):
        for c in range(m):
            v = grid[r][c]
            if v in (0,2):
                continue
            # Rays always go diagonally away from the nearest 2x2 object.
            if not blocks:
                continue
            br,bc=min(blocks,key=lambda b:abs(r-b[0])+abs(c-b[1]))
            dr = -1 if r < br else 1
            dc = -1 if c < bc else 1
            rr,cc=r+dr,c+dc
            while 0<=rr<n and 0<=cc<m:
                if g[rr][cc]==0:
                    g[rr][cc]=v
                rr+=dr;cc+=dc
    return g
